//! Arrow navigation for the nested and sliding submenus generated by GTK.
use gtk::prelude::*;
use gtk::{DirectionType, PopoverMenu, Widget};

type BoundMenus = std::rc::Rc<std::cell::RefCell<Vec<gtk::glib::WeakRef<PopoverMenu>>>>;

pub fn install(root: &impl IsA<Widget>) {
    let bound = BoundMenus::default();
    bind_tree(root.as_ref(), &bound);
    // GtkApplicationWindow creates its native menu bar when it is mapped.
    root.as_ref()
        .connect_map(move |root| bind_tree(root, &bound));
}

fn bind_tree(root: &Widget, bound: &BoundMenus) {
    visit(root, &mut |widget| {
        let Some(menu) = widget.downcast_ref::<PopoverMenu>() else {
            return;
        };
        {
            let mut menus = bound.borrow_mut();
            menus.retain(|m| m.upgrade().is_some());
            if menus.iter().any(|m| m.upgrade().as_ref() == Some(menu)) {
                return;
            }
            menus.push(menu.downgrade());
        }
        let registry = bound.clone();
        menu.connect_local("move-focus", false, move |values| {
            let menu = values[0].get::<PopoverMenu>().ok()?;
            let direction = values[1].get::<DirectionType>().ok()?;
            // Bind newly inserted children before opening one, even if its
            // asynchronous model-change idle callback has not run yet.
            bind_tree(menu.upcast_ref(), &registry);
            if navigate(&menu, direction) {
                menu.stop_signal_emission_by_name("move-focus");
            }
            None
        });
        let registry = bound.clone();
        menu.connect_map(move |menu| bind_tree(menu.upcast_ref(), &registry));
        if let Some(model) = menu.menu_model() {
            let weak = menu.downgrade();
            let registry = bound.clone();
            let handler = model.connect_items_changed(move |_, _, _, _| {
                let weak = weak.clone();
                let registry = registry.clone();
                // GTK must first finish building rows for the changed model.
                gtk::glib::idle_add_local_once(move || {
                    if let Some(menu) = weak.upgrade() {
                        bind_tree(menu.upcast_ref(), &registry);
                    }
                });
            });
            let handler = std::cell::RefCell::new(Some(handler));
            menu.connect_destroy(move |_| {
                if let Some(handler) = handler.borrow_mut().take() {
                    model.disconnect(handler);
                }
            });
        }
    });
}

fn visit(root: &Widget, f: &mut impl FnMut(&Widget)) {
    f(root);
    let mut child = root.first_child();
    while let Some(widget) = child {
        child = widget.next_sibling();
        visit(&widget, f);
    }
}

// This GTK row property predates flags/set_flags (GTK 4.14). Check for its
// presence rather than assuming a private widget type or changing the minimum
// supported GTK version. Ordinary action rows are never activated by an arrow.
fn menu_name(widget: &Widget) -> Option<String> {
    widget.find_property("menu-name")?;
    widget.property::<Option<String>>("menu-name")
}

fn page(menu: &PopoverMenu) -> Option<Widget> {
    let mut found = None;
    visit(menu.upcast_ref(), &mut |widget| {
        if found.is_none()
            && let Some(stack) = widget.downcast_ref::<gtk::Stack>()
        {
            found = stack.visible_child();
        }
    });
    found
}

fn first_link(page: &Widget, target: Option<&str>) -> Option<Widget> {
    let mut found = None;
    visit(page, &mut |widget| {
        if found.is_none()
            && let Some(name) = menu_name(widget)
            && target.is_none_or(|target| name == target)
        {
            found = Some(widget.clone());
        }
    });
    found
}

fn nested_menu(widget: &Widget) -> Option<PopoverMenu> {
    widget.find_property("popover")?;
    widget
        .property::<Option<Widget>>("popover")?
        .downcast()
        .ok()
}

fn parent_link(menu: &PopoverMenu) -> Option<Widget> {
    let mut parent = menu.parent();
    while let Some(widget) = parent {
        if nested_menu(&widget).as_ref() == Some(menu) {
            return Some(widget);
        }
        if widget.is::<gtk::PopoverMenuBar>() {
            break;
        }
        parent = widget.parent();
    }
    None
}

fn navigate(menu: &PopoverMenu, direction: DirectionType) -> bool {
    // Keyboard bindings can be delivered to an outer popover. Operate on the
    // deepest focused menu, so Left closes only the current submenu.
    let focus = menu.root().and_then(|root| root.focus());
    let focused_menu = focus
        .as_ref()
        .and_then(|w| w.ancestor(PopoverMenu::static_type()))
        .and_then(|w| w.downcast::<PopoverMenu>().ok())
        .filter(|child| child == menu || child.is_ancestor(menu));
    let menu = focused_menu.as_ref().unwrap_or(menu);
    let Some(current) = menu.visible_submenu() else {
        return false;
    };
    let Some(page) = page(menu) else {
        return false;
    };
    match direction {
        DirectionType::Left if current != "main" => {
            let Some(back) = first_link(&page, None) else {
                return false;
            };
            if !back.activate() {
                return false;
            }
            if let Some(parent) = self::page(menu)
                && let Some(opener) = first_link(&parent, Some(current.as_str()))
            {
                opener.grab_focus();
            }
            true
        }
        DirectionType::Left => {
            let Some(opener) = parent_link(menu) else {
                return false;
            };
            // popdown() deliberately cascades through GTK's menu chain.
            // Hide only this popover when navigating back to its parent.
            menu.set_visible(false);
            // Let GTK clear the parent's cached open submenu in this same
            // keypress. Otherwise subsequent arrows still target the hidden
            // child. popdown() is harmless now that the child is hidden.
            if let Some(parent) = opener
                .ancestor(PopoverMenu::static_type())
                .and_then(|widget| widget.downcast::<PopoverMenu>().ok())
            {
                parent.child_focus(DirectionType::Left);
            }
            opener.grab_focus();
            true
        }
        DirectionType::Right => {
            let Some(focus) = focus else {
                return false;
            };
            if !focus.is_ancestor(&page) {
                return false;
            }
            let nested = nested_menu(&focus);
            if menu_name(&focus).is_none() && nested.is_none() {
                return false;
            }
            if current != "main" && first_link(&page, None).as_ref() == Some(&focus) {
                return true;
            }
            if !focus.activate() {
                return false;
            }
            if let Some(submenu) = nested
                && !submenu
                    .root()
                    .and_then(|r| r.focus())
                    .is_some_and(|w| w.is_ancestor(&submenu))
            {
                submenu.child_focus(DirectionType::TabForward);
            }
            true
        }
        _ => false,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use gtk::{gio, glib};

    fn spin() {
        let context = glib::MainContext::default();
        while context.pending() {
            context.iteration(false);
        }
    }
    fn row(menu: &PopoverMenu, text: &str) -> Widget {
        let mut found = None;
        visit(&page(menu).unwrap(), &mut |widget| {
            if widget.find_property("text").is_some() && widget.property::<String>("text") == text {
                found = Some(widget.clone());
            }
        });
        found.unwrap_or_else(|| panic!("menu row missing: {text}"))
    }

    #[test]
    fn arrows_open_submenus_and_return_one_level_without_closing_the_menu() {
        crate::gtk_test::run(|| {
            let actions = gio::SimpleActionGroup::new();
            let open = gio::SimpleAction::new("open", None);
            let activated = std::rc::Rc::new(std::cell::Cell::new(0));
            let count = activated.clone();
            open.connect_activate(move |_, _| count.set(count.get() + 1));
            actions.add_action(&open);
            let local = gio::Menu::new();
            local.append(Some("Open project"), Some("win.open"));
            let projects = gio::Menu::new();
            projects.append(Some("Project A"), Some("win.open"));
            let remote = gio::Menu::new();
            remote.append_submenu(Some("Projects"), &projects);
            remote.append(Some("Connect"), Some("win.open"));
            let file = gio::Menu::new();
            file.append_submenu(Some("Local"), &local);
            file.append_submenu(Some("Remote"), &remote);
            let model = gio::Menu::new();
            model.append_submenu(Some("File"), &file);
            let app = gtk::Application::builder()
                .flags(gio::ApplicationFlags::NON_UNIQUE)
                .build();
            app.register(None::<&gio::Cancellable>).unwrap();
            app.set_menubar(Some(&model));
            let window = gtk::ApplicationWindow::builder()
                .application(&app)
                .default_width(640)
                .default_height(400)
                .build();
            window.set_show_menubar(true);
            window.insert_action_group("win", Some(&actions));
            install(&window);
            window.present();
            spin();
            let mut bar = None;
            visit(window.upcast_ref(), &mut |widget| {
                if bar.is_none() {
                    bar = widget.downcast_ref::<gtk::PopoverMenuBar>().cloned();
                }
            });
            let bar = bar.expect("application-generated menu bar");
            remote.remove_all();
            remote.append_submenu(Some("Projects"), &projects);
            remote.append(Some("Connect"), Some("win.open"));
            spin();
            let mut popover = None;
            visit(bar.upcast_ref(), &mut |w| {
                if popover.is_none() {
                    popover = w.downcast_ref::<PopoverMenu>().cloned();
                }
            });
            let menu = popover.expect("menu bar popover");
            window.present();
            spin();
            menu.popup();
            spin();
            for _ in 0..3 {
                for label in ["Local", "Remote"] {
                    let opener = row(&menu, label);
                    assert!(opener.grab_focus());
                    menu.emit_by_name::<()>("move-focus", &[&DirectionType::Right]);
                    spin();
                    let submenu = nested_menu(&opener).expect("menubar uses nested popovers");
                    assert!(submenu.is_visible(), "Right did not open {label}");
                    if label == "Remote" {
                        let projects = row(&submenu, "Projects");
                        assert!(projects.grab_focus());
                        submenu.emit_by_name::<()>("move-focus", &[&DirectionType::Right]);
                        spin();
                        let child = nested_menu(&projects).unwrap();
                        assert!(child.is_visible(), "Right did not open Projects");
                        assert!(row(&child, "Project A").grab_focus());
                        child.emit_by_name::<()>("move-focus", &[&DirectionType::Left]);
                        spin();
                        assert!(!child.is_visible(), "Left did not close Projects");
                        assert!(submenu.is_visible(), "Left closed Remote as well");
                        assert!(projects.is_focus(), "focus did not return to Projects");
                        submenu.emit_by_name::<()>("move-focus", &[&DirectionType::Down]);
                        spin();
                        assert!(
                            row(&submenu, "Connect").is_focus(),
                            "Down after Left did not move to Connect"
                        );
                    } else {
                        assert!(row(&submenu, "Open project").grab_focus());
                    }
                    submenu.emit_by_name::<()>("move-focus", &[&DirectionType::Left]);
                    spin();
                    assert!(!submenu.is_visible(), "Left did not return from {label}");
                    assert!(menu.is_visible(), "Left closed File as well");
                    assert!(opener.is_focus(), "focus did not return to {label}");
                    menu.emit_by_name::<()>(
                        "move-focus",
                        &[&if label == "Local" {
                            DirectionType::Down
                        } else {
                            DirectionType::Up
                        }],
                    );
                    spin();
                    assert!(
                        row(&menu, if label == "Local" { "Remote" } else { "Local" }).is_focus(),
                        "cannot move to sibling after returning from {label}"
                    );
                }
            }
            assert_eq!(
                activated.get(),
                0,
                "arrow navigation activated a project action"
            );
            window.close();
        });
    }
    #[test]
    fn sliding_submenu_returns_from_an_action_row_and_actions_still_activate() {
        crate::gtk_test::run(|| {
            let actions = gio::SimpleActionGroup::new();
            let action = gio::SimpleAction::new("open", None);
            let count = std::rc::Rc::new(std::cell::Cell::new(0));
            let observed = count.clone();
            action.connect_activate(move |_, _| observed.set(observed.get() + 1));
            actions.add_action(&action);
            let child = gio::Menu::new();
            child.append(Some("Open"), Some("win.open"));
            let model = gio::Menu::new();
            model.append_submenu(Some("Local"), &child);
            model.append(Some("Other"), Some("win.open"));
            let menu = PopoverMenu::from_model_full(&model, gtk::PopoverMenuFlags::empty());
            let button = gtk::MenuButton::new();
            button.set_popover(Some(&menu));
            let window = gtk::Window::builder()
                .child(&button)
                .default_width(400)
                .default_height(300)
                .build();
            window.insert_action_group("win", Some(&actions));
            install(&button);
            window.present();
            spin();
            menu.popup();
            spin();
            for _ in 0..3 {
                assert!(row(&menu, "Local").grab_focus());
                menu.emit_by_name::<()>("move-focus", &[&DirectionType::Right]);
                spin();
                assert_ne!(menu.visible_submenu().as_deref(), Some("main"));
                let leaf = row(&menu, "Open");
                assert!(leaf.grab_focus());
                assert!(
                    !navigate(&menu, DirectionType::Right),
                    "Right must not execute a leaf action"
                );
                menu.emit_by_name::<()>("move-focus", &[&DirectionType::Left]);
                spin();
                assert_eq!(menu.visible_submenu().as_deref(), Some("main"));
                assert!(menu.is_visible() && row(&menu, "Local").is_focus());
                menu.emit_by_name::<()>("move-focus", &[&DirectionType::Down]);
                spin();
                assert!(row(&menu, "Other").is_focus());
                menu.emit_by_name::<()>("move-focus", &[&DirectionType::Up]);
                spin();
                assert!(row(&menu, "Local").is_focus());
            }
            assert_eq!(count.get(), 0);
            row(&menu, "Local").grab_focus();
            menu.emit_by_name::<()>("move-focus", &[&DirectionType::Right]);
            spin();
            row(&menu, "Open").activate();
            spin();
            assert_eq!(count.get(), 1, "normal menu activation stopped working");
            assert!(!menu.is_visible());
            window.close();
        });
    }
}
